<?php require __DIR__.'/_layout.php';$u=require_admin();$pdo=db();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{$act=$_POST['action']??'import';if($act==='delete'){$pdo->prepare("DELETE FROM media WHERE id=?")->execute([(int)$_POST['id']]);go('instagram.php','Publicação removida do site.');}$lines=preg_split('/\R+/',trim($_POST['urls']??''));$added=0;$skipped=0;foreach($lines as $url){$url=trim($url);if($url===''||!instagram_url_valid($url)){$skipped++;continue;}$exists=$pdo->prepare("SELECT COUNT(*) FROM media WHERE instagram_url=?");$exists->execute([$url]);if((int)$exists->fetchColumn()>0){$skipped++;continue;}$pdo->prepare("INSERT INTO media(title,caption,media_type,instagram_url,sort_order,published,created_at) VALUES(?,?, 'INSTAGRAM', ?,100,1,?)")->execute([trim($_POST['title']??'Instagram BAMAB'),trim($_POST['caption']??''),$url,now_iso()]);$added++;}go('instagram.php',$added.' link(s) importado(s); '.$skipped.' ignorado(s).');}catch(Throwable $e){$err=$e->getMessage();}}$rows=$pdo->query("SELECT * FROM media WHERE media_type='INSTAGRAM' ORDER BY id DESC")->fetchAll();admin_header('Instagram — Importação em Lote');$msg=flash();?>
<?php if($msg):?><div class="alert ok"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?>
<div class="panel instagram-help"><h2>Instagram oficial cadastrado</h2><p><a href="<?=e(setting('instagram_url'))?>" target="_blank" rel="noopener noreferrer"><?=e(setting('instagram_url'))?></a></p><p>Para incorporar as publicações existentes ao site, copie os links dos posts/Reels no Instagram e cole abaixo — <strong>um link por linha</strong>. Você pode importar dezenas de uma vez.</p></div>
<form class="panel form-stack" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Links de posts / Reels<textarea name="urls" rows="12" required placeholder="https://www.instagram.com/p/...\nhttps://www.instagram.com/reel/...\nhttps://www.instagram.com/p/..."></textarea></label><div class="grid2"><label>Título padrão<input name="title" value="Instagram BAMAB"></label><label>Legenda padrão<input name="caption"></label></div><button class="primary">IMPORTAR LINKS PARA A GALERIA</button></form>
<div class="records"><?php foreach($rows as $r):?><article><div><span>INSTAGRAM</span><h3><?=e($r['title'])?></h3><a href="<?=e($r['instagram_url'])?>" target="_blank" rel="noopener noreferrer"><?=e($r['instagram_url'])?></a></div><form method="post" onsubmit="return confirm('Remover do site?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger">Excluir</button></form></article><?php endforeach;?></div>
<?php admin_footer();?>
